1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	import java.util.regex.Pattern;
5	
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Shared address handling for the owner pipelines. An address is normalized whenever an owner is
10	 * created: leading/trailing whitespace is trimmed, runs of whitespace are collapsed to a single
11	 * space, the text is upper-cased, and common street-type abbreviations are expanded
12	 * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). So {@code "  12  main  st "}
13	 * normalizes to {@code "12 MAIN STREET"}. The normalized form is what gets stored and returned, and
14	 * it is also the form used for every address comparison (household duplicate detection and the
15	 * shared household id).
16	 */
17	final class OwnerAddress {
18	
19	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
20	
21	    /** Common street-type abbreviations expanded to their full word (keys are upper-cased tokens). */
22	    private static final Map<String, String> ABBREVIATIONS = Map.of(
23	            "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
24	
25	    private OwnerAddress() {
26	    }
27	
28	    /** Normalizes the address on the request in place to its canonical form. */
29	    static void normalize(OwnerFieldsDto request) {
30	        request.setAddress(normalize(request.getAddress()));
31	    }
32	
33	    /**
34	     * Canonical form of a raw address: trimmed, whitespace-collapsed, upper-cased, with common
35	     * street-type abbreviations expanded. Returns {@code ""} for a null or whitespace-only value.
36	     */
37	    static String normalize(String value) {
38	        if (value == null) {
39	            return "";
40	        }
41	        String collapsed = WHITESPACE.matcher(value.trim()).replaceAll(" ");
42	        if (collapsed.isEmpty()) {
43	            return "";
44	        }
45	        String[] tokens = collapsed.toUpperCase().split(" ");
46	        StringBuilder sb = new StringBuilder(collapsed.length());
47	        for (String token : tokens) {
48	            if (sb.length() > 0) {
49	                sb.append(' ');
50	            }
51	            sb.append(ABBREVIATIONS.getOrDefault(token, token));
52	        }
53	        return sb.toString();
54	    }
55	}
