1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	import java.util.regex.Pattern;
5	
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerPostcodeException;
8	import org.springframework.samples.petclinic.util.Locality;
9	
10	/**
11	 * Shared postcode handling for the owner pipelines. An owner may include a {@code postcode}: it is
12	 * optional and validated only WHEN PRESENT, so an owner created without one is still accepted. When
13	 * present it must be four digits, and — if the owner's city maps to a known region — it must fall in
14	 * that region's fixed inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no
15	 * known region accepts any 4-digit postcode. Anything else is rejected with
16	 * {@link InvalidOwnerPostcodeException} (handled as 400). The trimmed postcode is stored and returned.
17	 */
18	final class OwnerPostcode {
19	
20	    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");
21	
22	    /** Region -> inclusive 4-digit postcode range {low, high}; regions not listed accept any 4 digits. */
23	    private static final Map<String, int[]> REGION_RANGE = Map.of(
24	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
25	
26	    private OwnerPostcode() {
27	    }
28	
29	    /**
30	     * Validates and normalizes the postcode on the request in place: a present, non-blank postcode is
31	     * trimmed and checked against the four-digit and city-region rules; a null or blank postcode is
32	     * left unchanged (absent postcodes are accepted).
33	     */
34	    static void validate(OwnerFieldsDto request) throws InvalidOwnerPostcodeException {
35	        String postcode = request.getPostcode();
36	        if (postcode == null || postcode.isBlank()) {
37	            return;
38	        }
39	        String trimmed = postcode.trim();
40	        if (!FOUR_DIGITS.matcher(trimmed).matches()) {
41	            throw new InvalidOwnerPostcodeException(postcode);
42	        }
43	        int[] range = REGION_RANGE.get(Locality.of(request.getCity()));
44	        if (range != null) {
45	            int value = Integer.parseInt(trimmed);
46	            if (value < range[0] || value > range[1]) {
47	                throw new InvalidOwnerPostcodeException(postcode);
48	            }
49	        }
50	        request.setPostcode(trimmed);
51	    }
52	}
